const queryClient = new QueryClient();
const basePath = import.meta.env.BASE_URL.replace(/\/$/, '');
const clerkPubKey = import.meta.env.VITE_CLERK_PUBLISHABLE_KEY;
const clerkProxyUrl = `${window.location.origin}/__clerk`;

const navItems = [
  { href: '/dashboard', label: 'Overview', icon: BarChart3 },
  { href: '/recommend', label: 'New recommendation', icon: Sparkles },
  { href: '/recommendations', label: 'History', icon: History },
  { href: '/materials', label: 'Materials library', icon: Database },
];

function cx(...values: Array<string | false | null | undefined>) { return values.filter(Boolean).join(' '); }
function formatDate(value?: string) { return value ? new Date(value).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }) : '—'; }
function initials(name?: string) { return (name || 'PS').split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase(); }

function Logo({ inverse = false }: { inverse?: boolean }) {
  return <Link href="/" className="flex items-center gap-2.5" data-testid="link-logo">
    <span className={cx('grid h-9 w-9 place-items-center rounded-xl', inverse ? 'bg-accent text-primary' : 'bg-primary text-accent')}>
      <PackageCheck size={19} strokeWidth={2.5} />
    </span>
    <span className={cx('display-face text-[1.05rem] font-bold tracking-tight', inverse ? 'text-sidebar-foreground' : 'text-foreground')}>PackSmart<span className="text-accent">.</span></span>
  </Link>;
}

function Button({ children, variant = 'primary', className, ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'ghost' | 'outline' | 'danger' }) {
  const styles = {
    primary: 'bg-primary text-primary-foreground hover:brightness-110',
    ghost: 'bg-transparent text-muted-foreground hover:bg-muted hover:text-foreground',
    outline: 'border border-border bg-card text-foreground hover:border-primary/40 hover:bg-muted',
    danger: 'bg-destructive text-destructive-foreground hover:brightness-110',
  };
  return <button {...props} className={cx('inline-flex min-h-10 items-center justify-center gap-2 rounded-lg px-4 text-sm font-semibold transition-all active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-50', styles[variant], className)}>{children}</button>;
}

function PageIntro({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle?: string; action?: ReactNode }) {
  const [location] = useLocation();
  const section = location.startsWith('/materials') ? 'Materials library' : location.startsWith('/recommendations') || location.startsWith('/recommend') ? 'Recommendations' : location.startsWith('/profile') ? 'Profile' : location.startsWith('/how-it-works') ? 'How it works' : location.startsWith('/faq') ? 'FAQ' : location.startsWith('/dashboard') ? 'Dashboard' : 'Workspace';
  return <div className="mb-8 reveal">
    <div className="mb-5 flex flex-wrap items-center gap-2 text-[11px] font-semibold text-muted-foreground" aria-label="Breadcrumb"><Link href="/" className="hover:text-primary">Home</Link><span className="text-border">/</span><Link href="/dashboard" className="hover:text-primary">Workspace</Link><span className="text-border">/</span><span className="text-foreground">{section}</span></div>
    <div className="flex flex-col justify-between gap-5 md:flex-row md:items-end">
      <div><div className="eyebrow mb-3 text-primary">{eyebrow}</div><h1 className="display-face text-3xl font-bold tracking-tight md:text-4xl">{title}</h1>{subtitle && <p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{subtitle}</p>}</div>
      {action}
    </div>
  </div>;
}

function PublicShell({ children }: { children: ReactNode }) {
  return <div className="min-h-[100dvh] bg-background">
    <header className="sticky top-0 z-30 border-b border-border/70 bg-background/90 backdrop-blur-md">
      <div className="mx-auto flex max-w-7xl items-center justify-between gap-4 px-5 py-4 md:px-8">
        <div className="flex items-center gap-5"><Logo /><Link href="/" className="hidden items-center gap-1 text-xs font-bold text-muted-foreground hover:text-primary sm:inline-flex" data-testid="link-back-home"><ChevronLeft size={14} /> Back to Home</Link></div>
        <nav className="hidden items-center gap-6 text-xs font-semibold text-muted-foreground md:flex"><Link href="/materials" className="hover:text-primary">Materials library</Link><Link href="/how-it-works" className="hover:text-primary">How it works</Link><Link href="/faq" className="hover:text-primary">FAQ</Link></nav>
        <div className="flex items-center gap-2"><Link href="/sign-in" className="hidden rounded-lg px-3 py-2 text-xs font-bold text-muted-foreground hover:bg-muted sm:block">Sign in</Link><Link href="/sign-up" className="inline-flex items-center gap-1.5 rounded-lg bg-primary px-3.5 py-2.5 text-xs font-bold text-primary-foreground hover:brightness-110">Start a brief <ArrowRight size={14} /></Link></div>
      </div>
    </header>
    <main className="mx-auto max-w-[1440px] px-5 py-8 md:px-8 lg:px-10">{children}</main>
  </div>;
}

function Skeleton({ className = '' }: { className?: string }) { return <div className={cx('shimmer rounded-lg', className)} aria-label="Loading" data-testid="loading-skeleton" />; }
function ErrorState({ onRetry, title = 'We could not load this view' }: { onRetry?: () => void; title?: string }) {
  return <div className="rounded-2xl border border-destructive/25 bg-destructive/5 p-8 text-center" data-testid="error-state"><CircleAlert className="mx-auto mb-3 text-destructive" /><h3 className="font-bold">{title}</h3><p className="mt-1 text-sm text-muted-foreground">Check your connection, then try again.</p>{onRetry && <Button variant="outline" className="mt-5" onClick={onRetry} data-testid="button-retry"><RefreshCw size={15} /> Retry</Button>}</div>;
}
function EmptyState({ icon: Icon = Clipboard, title, body, action }: { icon?: typeof Clipboard; title: string; body: string; action?: ReactNode }) {
  return <div className="grid min-h-56 place-items-center rounded-2xl border border-dashed border-border bg-card/60 p-10 text-center" data-testid="empty-state"><div><div className="mx-auto mb-4 grid h-12 w-12 place-items-center rounded-2xl bg-secondary text-primary"><Icon size={22} /></div><h3 className="font-bold">{title}</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-muted-foreground">{body}</p>{action && <div className="mt-5">{action}</div>}</div></div>;
}

function AppShell({ children }: { children: ReactNode }) {
  const [open, setOpen] = useState(false);
  const [location] = useLocation();
  const { user } = useUser();
  const { signOut } = useClerk();
  return <div className="grain flex min-h-[100dvh] bg-background">
    <aside className={cx('fixed inset-y-0 left-0 z-40 flex w-[258px] flex-col bg-sidebar px-4 py-5 transition-transform md:static md:translate-x-0', open ? 'translate-x-0' : '-translate-x-full')}>
      <div className="mb-9 px-2"><Logo inverse /></div>
      <div className="eyebrow px-3 pb-3 text-sidebar-foreground/45">Workspace</div>
      <nav className="space-y-1" aria-label="Main navigation">{navItems.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setOpen(false)} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`} className={cx('flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm transition-colors', location.startsWith(href) ? 'bg-sidebar-accent text-sidebar-foreground' : 'text-sidebar-foreground/65 hover:bg-sidebar-accent/70 hover:text-sidebar-foreground')}><Icon size={17} /><span>{label}</span>{href === '/recommend' && <span className="ml-auto rounded bg-accent px-1.5 py-0.5 font-mono text-[10px] text-accent-foreground">NEW</span>}</Link>)}</nav>
      <div className="mt-9 px-3 pb-3"><div className="eyebrow text-sidebar-foreground/45">Explore</div></div>
      <nav className="space-y-1"><Link href="/how-it-works" className="flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-foreground" data-testid="link-nav-how-it-works"><Beaker size={17} /> How it works</Link><Link href="/faq" className="flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-foreground" data-testid="link-nav-faq"><Info size={17} /> FAQ</Link></nav>
      <div className="mt-auto rounded-xl border border-sidebar-border bg-sidebar-accent/60 p-4"><div className="mb-2 flex items-center gap-2 text-accent"><ShieldCheck size={15} /><span className="eyebrow">Decision support</span></div><p className="text-xs leading-5 text-sidebar-foreground/60">Traceable recommendations grounded in material properties and your operating conditions.</p></div>
      <div className="mt-4 flex items-center gap-3 border-t border-sidebar-border pt-4"><div className="grid h-8 w-8 place-items-center rounded-full bg-accent font-mono text-xs font-bold text-accent-foreground">{initials(user?.fullName || user?.firstName || '')}</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold text-sidebar-foreground">{user?.fullName || user?.firstName || 'Your workspace'}</p><p className="truncate text-[11px] text-sidebar-foreground/45">{user?.primaryEmailAddress?.emailAddress || 'Account'}</p></div><button onClick={() => signOut({ redirectUrl: basePath || '/' })} className="text-sidebar-foreground/50 hover:text-accent" aria-label="Sign out" data-testid="button-sign-out"><LogOut size={15} /></button></div>
    </aside>
    {open && <button className="fixed inset-0 z-30 bg-foreground/30 md:hidden" onClick={() => setOpen(false)} aria-label="Close menu" data-testid="button-close-menu" />}
    <div className="min-w-0 flex-1">
      <header className="sticky top-0 z-20 flex h-[68px] items-center justify-between border-b border-border/70 bg-background/90 px-4 backdrop-blur-md md:px-8"><button className="mr-3 text-muted-foreground md:hidden" onClick={() => setOpen(true)} aria-label="Open menu" data-testid="button-open-menu"><Menu size={21} /></button><div className="hidden items-center gap-2 text-xs text-muted-foreground md:flex"><span className="h-1.5 w-1.5 rounded-full bg-accent" /> Materials intelligence workspace</div><div className="ml-auto flex items-center gap-2"><Link href="/materials" className="hidden rounded-lg px-3 py-2 text-xs font-semibold text-muted-foreground hover:bg-muted hover:text-foreground sm:block" data-testid="link-header-materials">Reference library</Link><Link href="/profile" className="grid h-9 w-9 place-items-center rounded-lg border border-border bg-card text-muted-foreground hover:text-primary" aria-label="Profile" data-testid="link-profile"><UserRound size={16} /></Link></div></header>
      <main className="mx-auto max-w-[1440px] px-4 py-8 md:px-8 lg:px-10">{children}</main>
    </div>
  </div>;
}

function HomeRedirect() {
  const { isLoaded, isSignedIn } = useAuth();
  if (!isLoaded) return <div className="grid min-h-[100dvh] place-items-center bg-background"><Skeleton className="h-10 w-40" /></div>;
  return isSignedIn ? <Redirect to="/dashboard" /> : <Landing />;
}

function Landing() {
  return <div className="min-h-[100dvh] overflow-hidden bg-background">
    <header className="mx-auto flex max-w-7xl items-center justify-between px-5 py-5 md:px-8"><Logo /><nav className="hidden items-center gap-7 text-sm font-semibold text-muted-foreground md:flex"><Link href="/materials" data-testid="link-home-materials">Materials library</Link><Link href="/how-it-works" data-testid="link-home-how-it-works">How it works</Link><Link href="/faq" data-testid="link-home-faq">FAQ</Link></nav><div className="flex items-center gap-2"><Link href="/sign-in" className="hidden rounded-lg px-3 py-2 text-sm font-semibold text-muted-foreground hover:bg-muted sm:block" data-testid="link-home-sign-in">Sign in</Link><Link href="/sign-up" className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground hover:brightness-110" data-testid="link-home-sign-up">Start a recommendation <ArrowRight size={15} /></Link></div></header>
    <section className="relative mx-auto max-w-7xl px-5 pb-20 pt-14 md:px-8 md:pb-28 md:pt-24"><div className="grid items-center gap-14 lg:grid-cols-[1.02fr_.98fr]"><div className="reveal"><div className="eyebrow mb-5 flex items-center gap-2 text-primary"><span className="h-2 w-2 rounded-full bg-accent" /> Packaging decisions, made practical</div><h1 className="display-face max-w-3xl text-5xl font-bold leading-[.98] tracking-[-.045em] md:text-7xl">Give every food product the <span className="relative whitespace-nowrap text-primary">right barrier<span className="absolute -bottom-1 left-0 h-1.5 w-full rounded-full bg-accent/80" /></span>.</h1><p className="mt-7 max-w-xl text-base leading-7 text-muted-foreground md:text-lg">PackSmart turns commodity behavior, storage realities, and transport risk into packaging specifications your team can act on.</p><div className="mt-9 flex flex-wrap items-center gap-3"><Link href="/sign-up" className="inline-flex items-center gap-2 rounded-lg bg-primary px-5 py-3 text-sm font-bold text-primary-foreground hover:brightness-110" data-testid="link-hero-start">Build a recommendation <ArrowRight size={16} /></Link><Link href="/materials" className="inline-flex items-center gap-2 rounded-lg border border-border bg-card px-5 py-3 text-sm font-bold hover:border-primary/40" data-testid="link-hero-library">Browse materials <Database size={16} /></Link></div><div className="mt-9 flex items-center gap-5 text-xs text-muted-foreground"><span className="flex items-center gap-2"><Check size={14} className="text-primary" /> Evidence-led outputs</span><span className="flex items-center gap-2"><Check size={14} className="text-primary" /> Built for real conditions</span></div></div><div className="relative reveal-2"><div className="grid-paper absolute -inset-8 -z-0 rounded-[2rem] opacity-60" /><div className="relative overflow-hidden rounded-[1.6rem] border border-primary/20 bg-primary p-5 shadow-2xl shadow-primary/10 md:p-7"><div className="mb-8 flex items-center justify-between border-b border-primary-foreground/15 pb-4"><div className="eyebrow text-accent">Live analysis / 04</div><span className="rounded-full border border-accent/40 px-2 py-1 font-mono text-[10px] text-accent">READY</span></div><div className="grid gap-3 sm:grid-cols-[1fr_150px]"><div><div className="eyebrow text-primary-foreground/55">Recommended structure</div><h2 className="display-face mt-2 text-3xl font-bold text-primary-foreground">PET / EVOH / PE</h2><p className="mt-2 text-sm text-primary-foreground/65">High-clarity rigid tray · 350 µm</p></div><div className="rounded-xl bg-primary-foreground/10 p-4"><div className="eyebrow text-primary-foreground/55">Fit score</div><div className="mt-1 text-4xl font-bold text-accent">91<span className="text-xl">/100</span></div><div className="mt-2 h-1 rounded-full bg-primary-foreground/15"><div className="h-full w-[91%] rounded-full bg-accent" /></div></div></div><div className="mt-8 grid grid-cols-3 gap-2">{[['O₂ barrier','Very high'],['WVTR','0.08 g/m²·day'],['MAP','Recommended']].map(([a,b]) => <div key={a} className="rounded-xl border border-primary-foreground/10 bg-primary-foreground/5 p-3"><div className="text-[10px] text-primary-foreground/50">{a}</div><div className="mt-1 text-xs font-semibold text-primary-foreground">{b}</div></div>)}</div><div className="mt-6 rounded-xl border border-accent/25 bg-accent/10 p-4"><div className="flex items-start gap-3"><Zap size={16} className="mt-0.5 text-accent" /><div><div className="text-xs font-bold text-accent">Why this fits</div><p className="mt-1 text-xs leading-5 text-primary-foreground/70">Strong oxygen control for high-sensitivity produce while keeping sealability and regional line compatibility in range.</p></div></div></div></div></div></div></section>
    <section className="border-y border-border bg-card/50"><div className="mx-auto grid max-w-7xl gap-0 px-5 md:grid-cols-3 md:px-8"><div className="border-border py-8 md:border-r md:pr-10"><div className="eyebrow text-primary">01 / Frame the brief</div><h3 className="mt-3 text-lg font-bold">Start with the product, not the polymer.</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Describe moisture, pH, respiration, shelf-life target, and route to market.</p></div><div className="border-border py-8 md:border-r md:px-10"><div className="eyebrow text-primary">02 / Compare options</div><h3 className="mt-3 text-lg font-bold">See the trade-offs clearly.</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Every recommendation shows why it fits, where it is weak, and what changes with an alternative.</p></div><div className="py-8 md:pl-10"><div className="eyebrow text-primary">03 / Take it forward</div><h3 className="mt-3 text-lg font-bold">Leave with a usable spec.</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Save the analysis, share a concise result, and keep the decision traceable.</p></div></div></section>
    <section className="mx-auto max-w-7xl px-5 py-20 md:px-8 md:py-28"><div className="grid gap-10 md:grid-cols-[.8fr_1.2fr]"><div><div className="eyebrow text-primary">A reference layer for the real world</div><h2 className="display-face mt-4 text-3xl font-bold tracking-tight md:text-5xl">Less hand-waving.<br />More operating context.</h2></div><div className="grid gap-4 sm:grid-cols-2"><div className="rounded-2xl border border-border bg-card p-6"><Thermometer className="text-primary" size={21} /><h3 className="mt-8 font-bold">Conditions matter</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Ambient, chilled, or frozen changes the packaging job. PackSmart keeps temperature and humidity in the frame.</p></div><div className="rounded-2xl border border-border bg-card p-6"><Leaf className="text-primary" size={21} /><h3 className="mt-8 font-bold">Sustainability with trade-offs</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Compare recyclable, compostable, and biodegradable paths without pretending protection is free.</p></div><div className="rounded-2xl border border-border bg-card p-6 sm:col-span-2"><Factory className="text-primary" size={21} /><h3 className="mt-8 font-bold">Useful to the whole packaging team</h3><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">For farmers, processors, startups, researchers, and packaging professionals who need a shared starting point for a decision.</p></div></div></div></section>
    <footer className="border-t border-border px-5 py-8 md:px-8"><div className="mx-auto flex max-w-7xl flex-col justify-between gap-3 text-xs text-muted-foreground sm:flex-row"><span>© {new Date().getFullYear()} PackSmart AI</span><span>Decision support for safer, smarter packaging.</span></div></footer>
  </div>;
}

function Protected({ children }: { children: ReactNode }) {
  const { isLoaded, isSignedIn } = useAuth();
  if (!isLoaded) return <div className="grid min-h-[100dvh] place-items-center"><Skeleton className="h-10 w-40" /></div>;
  if (!isSignedIn) return <Redirect to="/sign-in" />;
  return <AppShell>{children}</AppShell>;
}

function Dashboard() {
  const { data, isLoading, isError, refetch } = useGetDashboardSummary();
  return <><PageIntro eyebrow="Workspace / overview" title="Good decisions start with a clear brief." subtitle="Your packaging work, in one place." action={<Link href="/recommend" className="inline-flex items-center justify-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground hover:brightness-110" data-testid="link-dashboard-new"><Sparkles size={16} /> New recommendation</Link>} />{isLoading ? <DashboardSkeleton /> : isError ? <ErrorState onRetry={() => refetch()} /> : <div className="space-y-7"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{[['Analyses run', data?.totalRecommendations ?? 0, 'all time'],['Last 30 days', data?.recentRecommendations ?? 0, 'recent briefs'],['Saved products', data?.savedProducts ?? 0, 'in your library'],['Avg. shelf life', data?.averageShelfLife ?? '—', 'across analyses']].map(([label, value, note], index) => <div key={label as string} className={cx('rounded-2xl border border-border bg-card p-5 reveal', `reveal-${Math.min(index + 1, 3)}`)}><div className="eyebrow text-muted-foreground">{label}</div><div className="mt-4 text-3xl font-bold tracking-tight" data-testid={`metric-${String(label).toLowerCase().replaceAll(' ', '-')}`}>{value}</div><div className="mt-1 text-xs text-muted-foreground">{note}</div></div>)}</div><div className="grid gap-7 lg:grid-cols-[1.25fr_.75fr]"><section className="rounded-2xl border border-border bg-card p-5 md:p-6"><div className="mb-5 flex items-center justify-between"><div><div className="eyebrow text-primary">Recent work</div><h2 className="mt-1 text-lg font-bold">Latest recommendations</h2></div><Link href="/recommendations" className="text-xs font-bold text-primary hover:underline" data-testid="link-dashboard-history">View all</Link></div>{data?.latest?.length ? <div className="divide-y divide-border">{data.latest.slice(0, 5).map((item) => <RecommendationRow key={item.id} item={item} />)}</div> : <EmptyState icon={Sparkles} title="Your first decision is waiting" body="Run a recommendation to see a tailored structure, spec, and trade-off analysis here." action={<Link href="/recommend" className="text-sm font-bold text-primary" data-testid="link-empty-recommend">Start a recommendation <ArrowRight size={14} className="inline" /></Link>} />}</section><section className="rounded-2xl border border-border bg-card p-5 md:p-6"><div className="eyebrow text-primary">Material signal</div><h2 className="mt-1 text-lg font-bold">What teams reach for</h2><p className="mt-2 text-xs leading-5 text-muted-foreground">Your most-used recommended materials.</p><div className="mt-7 space-y-5">{data?.topMaterials?.length ? data.topMaterials.map((material) => <div key={material.materialName}><div className="mb-2 flex justify-between text-xs"><span className="font-semibold">{material.materialName}</span><span className="font-mono text-muted-foreground">{material.count} {material.count === 1 ? 'use' : 'uses'}</span></div><div className="h-2 rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${Math.min(100, 24 + material.count * 13)}%` }} /></div></div>) : <p className="mt-5 text-sm text-muted-foreground">No material trend yet.</p>}</div></section></div></div>}</>;
}
function DashboardSkeleton() { return <div className="space-y-7"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{[1,2,3,4].map((x) => <Skeleton key={x} className="h-32" />)}</div><div className="grid gap-7 lg:grid-cols-[1.25fr_.75fr]"><Skeleton className="h-80" /><Skeleton className="h-80" /></div></div>; }
function RecommendationRow({ item }: { item: RecommendationSummary }) { return <Link href={`/recommendations/${item.id}`} className="flex items-center gap-4 py-4 hover:bg-muted/45" data-testid={`link-recommendation-${item.id}`}><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-secondary text-primary"><PackageCheck size={18} /></div><div className="min-w-0 flex-1"><div className="truncate text-sm font-bold">{item.commodityName}</div><div className="mt-1 truncate text-xs text-muted-foreground">{item.materialName} · {item.storageType} · {item.shelfLife}</div></div><div className="hidden text-right sm:block"><div className="font-mono text-xs font-semibold text-primary">{item.strength}</div><div className="mt-1 text-[11px] text-muted-foreground">{formatDate(item.createdAt)}</div></div><ChevronRight size={16} className="text-muted-foreground" /></Link>; }

const defaultInput: RecommendationInput = { commodityName: '', category: '', properties: { moistureContent: 12, oilContent: 1, ph: 6.2, respirationRate: 'medium', respirationNumeric: 0, oxygenSensitivity: 'medium', lightSensitivity: 'medium', microbialSensitivity: 'medium', textureSensitivity: 'medium' }, storage: { shelfLifeValue: 14, shelfLifeUnit: 'days', storageType: 'chilled', temperature: 4, humidity: 75, lightExposure: 'medium' }, transportation: { type: 'regional', durationValue: 2, durationUnit: 'days', mechanicalStress: 'medium', temperatureFluctuation: 'medium', humidityExposure: 'medium', handlingConditions: 'moderate' }, preferences: { priority: 'balanced', sustainability: 'recyclable', budget: 'standard', mapRequired: 'auto', packageType: 'Flexible pouch' } };

const wizardSteps = [{ title: 'Product', note: 'What are you packing?' }, { title: 'Properties', note: 'How does it behave?' }, { title: 'Storage', note: 'Where will it wait?' }, { title: 'Transport', note: 'How will it move?' }, { title: 'Priorities', note: 'What matters most?' }, { title: 'Review', note: 'Check your brief' }];
function Field({ label, hint, children }: { label: string; hint?: string; children: ReactNode }) { return <label className="block"><span className="mb-2 flex items-baseline justify-between text-xs font-bold"><span>{label}</span>{hint && <span className="font-normal text-muted-foreground">{hint}</span>}</span>{children}</label>; }
function Input({ className, ...props }: InputHTMLAttributes<HTMLInputElement>) { return <input {...props} className={cx('h-11 w-full rounded-lg border border-input bg-background px-3 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15', className)} />; }
function Select({ className, ...props }: SelectHTMLAttributes<HTMLSelectElement>) { return <select {...props} className={cx('h-11 w-full rounded-lg border border-input bg-background px-3 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15', className)} />; }
function WizardStep({ step }: { step: number }) {
  const { register, setValue } = useFormContext<RecommendationInput>();
  const { data: commodities } = useListCommodities();
  if (step === 0) return <div className="space-y-6"><div className="grid gap-5 md:grid-cols-2"><Field label="Commodity or product" hint="Required"><Input {...register('commodityName', { required: true })} placeholder="e.g. fresh-cut mango" data-testid="input-commodity-name" /></Field><Field label="Category"><Input {...register('category', { required: true })} placeholder="e.g. fresh produce" data-testid="input-category" /></Field></div><div><div className="mb-3 text-xs font-bold">Starter commodities</div><div className="flex flex-wrap gap-2">{commodities?.slice(0, 8).map((item) => <button type="button" key={item.id} onClick={() => { setValue('commodityName', item.name, { shouldDirty: true }); setValue('category', item.category, { shouldDirty: true }); }} className="rounded-full border border-border bg-card px-3 py-2 text-xs font-semibold text-muted-foreground hover:border-primary/40 hover:text-primary" data-testid={`button-commodity-${item.id}`}>{item.name}</button>)}</div><p className="mt-3 text-xs text-muted-foreground">Use the quick picks as a starting point, then refine the brief on the next step.</p></div><div className="rounded-xl border border-primary/15 bg-secondary/60 p-4 text-sm leading-6 text-muted-foreground"><Info size={16} className="mr-2 inline text-primary" /> PackSmart uses your product behavior as the anchor. The material comes later.</div></div>;
  if (step === 1) return <div className="space-y-5"><div className="grid gap-5 sm:grid-cols-3"><Field label="Moisture content" hint="%"><Input type="number" step=".1" {...register('properties.moistureContent', { valueAsNumber: true })} data-testid="input-moisture-content" /></Field><Field label="Oil content" hint="%"><Input type="number" step=".1" {...register('properties.oilContent', { valueAsNumber: true })} data-testid="input-oil-content" /></Field><Field label="pH"><Input type="number" step=".1" {...register('properties.ph', { valueAsNumber: true })} data-testid="input-ph" /></Field></div><div className="grid gap-5 sm:grid-cols-2"><Field label="Respiration rate"><Select {...register('properties.respirationRate')} data-testid="select-respiration"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option><option value="very-high">Very high</option></Select></Field><Field label="Oxygen sensitivity"><Select {...register('properties.oxygenSensitivity')} data-testid="select-oxygen"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></Select></Field><Field label="Light sensitivity"><Select {...register('properties.lightSensitivity')} data-testid="select-light"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></Select></Field><Field label="Microbial sensitivity"><Select {...register('properties.microbialSensitivity')} data-testid="select-microbial"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></Select></Field><Field label="Texture sensitivity"><Select {...register('properties.textureSensitivity')} data-testid="select-texture"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></Select></Field></div></div>;
  if (step === 2) return <div className="space-y-5"><div className="grid gap-5 sm:grid-cols-2"><Field label="Shelf-life target"><div className="flex gap-2"><Input type="number" {...register('storage.shelfLifeValue', { valueAsNumber: true })} data-testid="input-shelf-life" /><Select className="w-32" {...register('storage.shelfLifeUnit')} data-testid="select-shelf-life-unit"><option value="days">days</option><option value="weeks">weeks</option><option value="months">months</option></Select></div></Field><Field label="Storage type"><Select {...register('storage.storageType')} data-testid="select-storage-type"><option value="ambient">Ambient</option><option value="chilled">Chilled</option><option value="frozen">Frozen</option></Select></Field><Field label="Temperature" hint="°C"><Input type="number" {...register('storage.temperature', { valueAsNumber: true })} data-testid="input-temperature" /></Field><Field label="Relative humidity" hint="%"><Input type="number" {...register('storage.humidity', { valueAsNumber: true })} data-testid="input-humidity" /></Field></div><Field label="Light exposure"><Select {...register('storage.lightExposure')} data-testid="select-light-exposure"><option value="low">Low / opaque storage</option><option value="medium">Medium / mixed</option><option value="high">High / retail display</option></Select></Field></div>;
  if (step === 3) return <div className="space-y-5"><div className="grid gap-5 sm:grid-cols-2"><Field label="Distribution route"><Select {...register('transportation.type')} data-testid="select-route"><option value="local">Local</option><option value="regional">Regional</option><option value="national">National</option><option value="export">Export</option></Select></Field><Field label="Transit duration"><div className="flex gap-2"><Input type="number" {...register('transportation.durationValue', { valueAsNumber: true })} data-testid="input-transit-duration" /><Select className="w-32" {...register('transportation.durationUnit')} data-testid="select-transit-unit"><option value="hours">hours</option><option value="days">days</option></Select></div></Field><Field label="Mechanical stress"><Select {...register('transportation.mechanicalStress')} data-testid="select-mechanical-stress"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></Select></Field><Field label="Temperature fluctuation"><Select {...register('transportation.temperatureFluctuation')} data-testid="select-temp-fluctuation"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></Select></Field><Field label="Humidity exposure"><Select {...register('transportation.humidityExposure')} data-testid="select-humidity-exposure"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></Select></Field><Field label="Handling conditions"><Select {...register('transportation.handlingConditions')} data-testid="select-handling"><option value="controlled">Controlled</option><option value="moderate">Moderate</option><option value="rough">Rough</option></Select></Field></div></div>;
  if (step === 4) return <div className="space-y-5"><Field label="Decision priority"><Select {...register('preferences.priority')} data-testid="select-priority"><option value="balanced">Balanced</option><option value="shelf-life">Shelf life</option><option value="protection">Protection</option><option value="cost">Cost</option><option value="sustainability">Sustainability</option></Select></Field><div className="grid gap-5 sm:grid-cols-2"><Field label="Sustainability direction"><Select {...register('preferences.sustainability')} data-testid="select-sustainability"><option value="none">No specific requirement</option><option value="recyclable">Recyclable</option><option value="biodegradable">Biodegradable</option><option value="compostable">Compostable</option><option value="strong">Strong preference</option></Select></Field><Field label="Budget band"><Select {...register('preferences.budget')} data-testid="select-budget"><option value="economy">Economy</option><option value="standard">Standard</option><option value="premium">Premium</option></Select></Field><Field label="MAP requirement"><Select {...register('preferences.mapRequired')} data-testid="select-map"><option value="auto">Let PackSmart assess</option><option value="yes">Required</option><option value="no">Not required</option></Select></Field><Field label="Package format"><Input {...register('preferences.packageType')} placeholder="e.g. flexible pouch" data-testid="input-package-type" /></Field></div></div>;
  const { watch } = useFormContext<RecommendationInput>(); const values = watch();
  return <div className="space-y-4"><div className="rounded-xl border border-border bg-muted/30 p-5"><div className="grid gap-y-4 text-sm sm:grid-cols-2"><div><span className="text-xs text-muted-foreground">Commodity</span><p className="mt-1 font-bold">{values.commodityName || 'Not set'} <span className="font-normal text-muted-foreground">/ {values.category || 'category not set'}</span></p></div><div><span className="text-xs text-muted-foreground">Shelf-life target</span><p className="mt-1 font-bold">{values.storage.shelfLifeValue} {values.storage.shelfLifeUnit} · {values.storage.storageType}</p></div><div><span className="text-xs text-muted-foreground">Operating conditions</span><p className="mt-1 font-bold">{values.storage.temperature}°C · {values.storage.humidity}% RH · {values.transportation.type}</p></div><div><span className="text-xs text-muted-foreground">Decision frame</span><p className="mt-1 font-bold capitalize">{values.preferences.priority} · {values.preferences.sustainability}</p></div></div></div><div className="flex items-start gap-3 rounded-xl border border-accent/30 bg-accent/10 p-4 text-sm leading-6"><Target size={17} className="mt-1 shrink-0 text-primary" /><p>We will score material fit against the product, shelf-life, transport stress, and sustainability constraints you gave us. The output is decision support, not a compliance certificate.</p></div></div>;
}

function Recommend() {
  const [step, setStep] = useState(0); const [result, setResult] = useState<RecommendationResult | null>(null); const [saved, setSaved] = useState<number | null>(null);
  const form = useForm<RecommendationInput>({ defaultValues: defaultInput }); const analyze = useAnalyzeRecommendation(); const save = useSaveRecommendation(); const [, setLocation] = useLocation();
  if (result) return <ResultView result={result} input={form.getValues()} saved={saved} onSave={() => save.mutate({ data: { input: form.getValues(), result } }, { onSuccess: (item) => { setSaved(item.id); queryClient.invalidateQueries({ queryKey: getListRecommendationsQueryKey() }); } })} saving={save.isPending} onReset={() => { setResult(null); setSaved(null); setStep(0); }} onOpen={() => saved && setLocation(`/recommendations/${saved}`)} />;
  const onSubmit = form.handleSubmit((input) => analyze.mutate({ data: input }, { onSuccess: setResult }));
  return <div className="mx-auto max-w-4xl"><PageIntro eyebrow={`Recommendation / ${String(step + 1).padStart(2, '0')} of 06`} title="Build a packaging brief." subtitle="A short, structured intake gives the analysis enough context to be useful." /><div className="mb-7 grid grid-cols-6 gap-1.5">{wizardSteps.map((item, index) => <button type="button" key={item.title} onClick={() => index < step && setStep(index)} className="group text-left" data-testid={`button-step-${index + 1}`}><div className={cx('mb-2 h-1 rounded-full transition-colors', index <= step ? 'bg-primary' : 'bg-border')} /><div className={cx('hidden text-[11px] font-semibold sm:block', index === step ? 'text-primary' : 'text-muted-foreground')}>{item.title}</div></button>)}</div><FormProvider {...form}><form onSubmit={onSubmit} className="rounded-2xl border border-border bg-card p-5 shadow-sm md:p-8"><div className="mb-7 flex items-start justify-between border-b border-border pb-5"><div><div className="eyebrow text-primary">Step {String(step + 1).padStart(2, '0')}</div><h2 className="mt-1 text-xl font-bold">{wizardSteps[step].title}</h2><p className="mt-1 text-sm text-muted-foreground">{wizardSteps[step].note}</p></div><div className="hidden rounded-lg bg-secondary px-3 py-2 text-right sm:block"><div className="font-mono text-xs font-bold text-primary">{Math.round(((step + 1) / 6) * 100)}%</div><div className="text-[10px] text-muted-foreground">brief complete</div></div></div><WizardStep step={step} /><div className="mt-9 flex items-center justify-between border-t border-border pt-5"><Button type="button" variant="ghost" disabled={step === 0} onClick={() => setStep((s) => s - 1)} data-testid="button-wizard-back"><ChevronLeft size={16} /> Back</Button>{step < 5 ? <Button type="button" onClick={() => setStep((s) => s + 1)} data-testid="button-wizard-next">Continue <ChevronRight size={16} /></Button> : <Button type="submit" disabled={analyze.isPending} data-testid="button-run-analysis">{analyze.isPending ? <><RefreshCw size={15} className="animate-spin" /> Analyzing brief…</> : <><Sparkles size={15} /> Run analysis</>}</Button>}</div>{analyze.isError && <div className="mt-4 flex items-center gap-2 rounded-lg bg-destructive/10 p-3 text-xs text-destructive" data-testid="status-analysis-error"><CircleAlert size={15} /> Analysis failed. Please review the brief and try again.</div>}</form></FormProvider></div>;
}

function ScoreBadge({ score, strength }: { score: number; strength: string }) { return <div className="flex items-center gap-3"><div className="grid h-16 w-16 place-items-center rounded-full border-[5px] border-accent bg-accent/10"><span className="font-mono text-xl font-bold text-primary">{score}</span></div><div><div className="eyebrow text-primary">Fit score</div><div className="mt-1 text-sm font-bold capitalize">{strength} match</div></div></div>; }

type PreviewLayer = { role: string; name: string; tone: string };
type PackagingProfile = {
  silhouette: 'pouch' | 'tray' | 'paper';
  variant: 'standard' | 'metallic' | 'clear' | 'paper' | 'perforated' | 'compostable';
  label: string;
  surface: string;
  layers: PreviewLayer[];
  showWindow: boolean;
  windowLabel: string;
  colors: { front: string; side: string; top: string; ink: string; window: string; border: string };
};

const profileColors = {
  green: { front: '#267d70', side: '#15584f', top: '#e4b64e', ink: '#f8f5e9', window: 'rgba(248,245,233,.14)', border: 'rgba(248,245,233,.38)' },
  clear: { front: '#70a9a0', side: '#3d7770', top: '#d8b65c', ink: '#143e39', window: 'rgba(245,250,247,.58)', border: 'rgba(20,62,57,.28)' },
  silver: { front: '#82909a', side: '#4e5b63', top: '#d8b24c', ink: '#f6f2e7', window: 'rgba(246,242,231,.08)', border: 'rgba(246,242,231,.42)' },
  paper: { front: '#c28e58', side: '#8f6038', top: '#e2b762', ink: '#fff8e8', window: 'rgba(255,248,232,.18)', border: 'rgba(255,248,232,.42)' },
  bio: { front: '#9caa62', side: '#6c7c42', top: '#e1bc5a', ink: '#fff8e8', window: 'rgba(255,248,232,.2)', border: 'rgba(255,248,232,.42)' },
  perforated: { front: '#5e9ab1', side: '#376b7f', top: '#e3bb58', ink: '#f5fbf5', window: 'rgba(245,251,245,.2)', border: 'rgba(245,251,245,.4)' },
} as const;

function getPackagingProfile(material: Material, packageType = ''): PackagingProfile {
  const id = material.id.toLowerCase();
  const type = packageType.toLowerCase();
  if (id === 'aluminum-foil-laminate') return { silhouette: 'pouch', variant: 'metallic', label: 'FOIL LAMINATE', surface: 'Opaque, reflective barrier pouch', showWindow: false, windowLabel: 'FULL BARRIER', colors: profileColors.silver, layers: [{ role: 'Outer web', name: 'PET print layer', tone: '#aeb9c1' }, { role: 'Barrier', name: 'Aluminium foil', tone: '#e2bd55' }, { role: 'Sealant', name: 'PE inner sealant', tone: '#e8eee9' }] };
  if (id === 'metallized-pet') return { silhouette: 'pouch', variant: 'metallic', label: 'MET PET', surface: 'Metallized, light-blocking film', showWindow: false, windowLabel: 'LIGHT BLOCK', colors: profileColors.silver, layers: [{ role: 'Outer web', name: 'PET structural film', tone: '#aeb9c1' }, { role: 'Barrier', name: 'Vacuum metallized layer', tone: '#d6ab48' }, { role: 'Sealant', name: 'PE or CPP sealant', tone: '#e8eee9' }] };
  if (id === 'evoh-multilayer') return { silhouette: 'tray', variant: 'clear', label: 'EVOH MULTILAYER', surface: 'Clear rigid pack with oxygen barrier core', showWindow: true, windowLabel: 'PRODUCT VIEW', colors: profileColors.clear, layers: [{ role: 'Structure', name: 'PET / PP structural layer', tone: '#78aaa4' }, { role: 'Barrier', name: 'EVOH oxygen barrier', tone: '#e2b64e' }, { role: 'Sealant', name: 'PE sealant layer', tone: '#d8eee7' }] };
  if (id === 'paper-based-laminate') return { silhouette: 'paper', variant: 'paper', label: 'PAPER LAMINATE', surface: 'Fiber outer web with coated inner barrier', showWindow: false, windowLabel: 'COATED INNER', colors: profileColors.paper, layers: [{ role: 'Outer web', name: 'Paper fiber layer', tone: '#c89762' }, { role: 'Barrier', name: 'Functional coating', tone: '#e3b64e' }, { role: 'Sealant', name: 'Inner polymer coating', tone: '#f0dfb8' }] };
  if (id === 'biodegradable-film' || id === 'compostable-film') return { silhouette: 'pouch', variant: 'compostable', label: id === 'compostable-film' ? 'COMPOSTABLE FILM' : 'BIODEGRADABLE FILM', surface: 'Bio-based film with defined end-of-life path', showWindow: true, windowLabel: 'BIO-BASED', colors: profileColors.bio, layers: [{ role: 'Outer web', name: 'Bio-based film', tone: '#9eae67' }, { role: 'Barrier', name: 'Functional barrier coating', tone: '#e0b952' }, { role: 'Sealant', name: 'Compostable sealant', tone: '#e7e0b6' }] };
  if (id === 'breathable-film' || id === 'micro-perforated-film') return { silhouette: 'pouch', variant: 'perforated', label: id === 'micro-perforated-film' ? 'MICRO-PERFORATED' : 'BREATHABLE FILM', surface: 'Controlled gas-exchange film', showWindow: true, windowLabel: 'GAS EXCHANGE', colors: profileColors.perforated, layers: [{ role: 'Outer web', name: 'Permeable film', tone: '#63a2b5' }, { role: 'Barrier', name: id === 'micro-perforated-film' ? 'Micro-perforation field' : 'Breathable pathway', tone: '#e0b64e' }, { role: 'Sealant', name: 'Sealable edge layer', tone: '#d2ece9' }] };
  if (id === 'bopp' || id === 'ldpe' || id === 'hdpe' || type.includes('flexible')) return { silhouette: 'pouch', variant: 'standard', label: material.name.toUpperCase(), surface: 'Flexible film pouch', showWindow: true, windowLabel: 'FILM VIEW', colors: profileColors.green, layers: [{ role: 'Outer web', name: `${material.name} film`, tone: '#2a8377' }, { role: 'Barrier', name: `${material.properties.oxygenBarrier} oxygen layer`, tone: '#e1b650' }, { role: 'Sealant', name: material.properties.sealability, tone: '#d8eee7' }] };
  return { silhouette: type.includes('tray') || type.includes('rigid') ? 'tray' : 'pouch', variant: 'clear', label: material.name.toUpperCase(), surface: material.category, showWindow: true, windowLabel: 'STRUCTURE VIEW', colors: profileColors.clear, layers: [{ role: 'Structure', name: `${material.name} structural layer`, tone: '#70a59d' }, { role: 'Barrier', name: `${material.properties.oxygenBarrier} oxygen barrier`, tone: '#dfb44d' }, { role: 'Sealant', name: material.properties.sealability, tone: '#d8eee7' }] };
}

function PackagingPreview({ material, packageType = 'Flexible pouch' }: { material: Material; packageType?: string }) {
  const profile = useMemo(() => getPackagingProfile(material, packageType), [material, packageType]);
  const [rotation, setRotation] = useState({ x: -8, y: -18 });
  const [dragging, setDragging] = useState(false);
  const pointerStart = useRef({ pointerId: -1, x: 0, y: 0, rx: 0, ry: 0 });
  const stageRef = useRef<HTMLDivElement>(null);
  const visualStyle = {
    '--package-front': profile.colors.front,
    '--package-side': profile.colors.side,
    '--package-top': profile.colors.top,
    '--package-ink': profile.colors.ink,
    '--package-window': profile.colors.window,
    '--package-border': profile.colors.border,
  } as CSSProperties;

  useEffect(() => { setRotation({ x: -8, y: -18 }); setDragging(false); }, [material.id]);
  useEffect(() => {
    if (dragging) return;
    const timer = window.setInterval(() => setRotation((current) => ({ ...current, y: current.y + 0.35 })), 70);
    return () => window.clearInterval(timer);
  }, [dragging]);

  const stopDragging = () => {
    const stage = stageRef.current;
    if (stage?.hasPointerCapture(pointerStart.current.pointerId)) stage.releasePointerCapture(pointerStart.current.pointerId);
    setDragging(false);
  };

  return <section className="rounded-2xl border border-border bg-card p-5 md:p-6" data-testid="card-packaging-preview">
    <div className="flex flex-wrap items-start justify-between gap-3"><div><div className="eyebrow text-primary">Material-aware spatial preview</div><h2 className="mt-1 text-lg font-bold">How this structure comes together</h2><p className="mt-1 text-xs text-muted-foreground">{profile.surface}. Drag the preview to inspect the form and layer stack.</p></div><span className="rounded-full bg-secondary px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider text-primary">{packageType || 'Package mockup'}</span></div>
    <div className="mt-6 grid gap-6 lg:grid-cols-[1fr_.8fr] lg:items-center">
      <div ref={stageRef} className="package-stage" onPointerDown={(event) => { if (event.button !== 0) return; event.currentTarget.setPointerCapture(event.pointerId); pointerStart.current = { pointerId: event.pointerId, x: event.clientX, y: event.clientY, rx: rotation.x, ry: rotation.y }; setDragging(true); }} onPointerMove={(event) => { if (!dragging || event.pointerId !== pointerStart.current.pointerId) return; setRotation({ x: Math.max(-28, Math.min(28, pointerStart.current.rx - (event.clientY - pointerStart.current.y) * 0.35)), y: pointerStart.current.ry + (event.clientX - pointerStart.current.x) * 0.5 }); }} onPointerUp={stopDragging} onPointerCancel={stopDragging} onLostPointerCapture={() => setDragging(false)} onDoubleClick={() => setRotation({ x: -8, y: -18 })} role="img" aria-label={`Interactive ${profile.label.toLowerCase()} preview for ${material.name}`}>
        <div className={cx('package-model', `package-model--${profile.silhouette}`, `package-model--${profile.variant}`)} data-silhouette={profile.silhouette} data-variant={profile.variant} style={{ ...visualStyle, transform: `perspective(850px) rotateX(${rotation.x}deg) rotateY(${rotation.y}deg)` }}>
          <div className="package-face package-front"><div className="package-brand">PACK<span>SMART</span></div><div className={cx('package-window', !profile.showWindow && 'package-window--opaque')}><span>{profile.windowLabel}</span></div><div className="package-label">{profile.label}</div></div>
          <div className="package-face package-side" /><div className="package-face package-top" /><div className="package-shadow" />
        </div>
        <div className="package-hint">{dragging ? 'Release to inspect' : 'Drag to rotate · double-click to reset'}</div>
      </div>
      <div className="space-y-2" aria-label="Material layer indicators"><div className="mb-3 flex items-center justify-between gap-3 text-xs font-bold text-muted-foreground"><span>Actual material stack</span><span className="font-mono text-[10px] text-primary">{material.thicknessRange}</span></div>{profile.layers.map((layer, index) => <div key={`${layer.role}-${layer.name}`} className="flex items-center gap-3 rounded-xl border border-border bg-background p-3"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-lg font-mono text-[10px] font-bold text-primary" style={{ backgroundColor: `${layer.tone}2a` }}>{String(index + 1).padStart(2, '0')}</span><span className="h-7 w-1 shrink-0 rounded-full" style={{ backgroundColor: layer.tone }} /><div><div className="text-xs font-bold">{layer.role}</div><div className="text-xs text-muted-foreground">{layer.name}</div></div></div>)}</div>
    </div>
  </section>;
}

function ResultViewContent({ result, input, saved, onSave, saving, onReset, onOpen }: { result: RecommendationResult; input: RecommendationInput; saved: number | null; onSave: () => void; saving: boolean; onReset: () => void; onOpen: () => void }) {
  const [expanded, setExpanded] = useState(false);
  return <div className="mx-auto max-w-6xl"><div className="mb-6 flex flex-wrap items-center justify-between gap-3"><div><div className="eyebrow text-primary">Analysis complete / engine {result.engineVersion}</div><h1 className="display-face mt-2 text-3xl font-bold tracking-tight">A defensible starting point.</h1><p className="mt-2 text-sm text-muted-foreground">{input.commodityName} · {input.storage.shelfLifeValue} {input.storage.shelfLifeUnit} · {input.storage.storageType}</p></div><div className="flex gap-2"><Button variant="outline" onClick={onReset} data-testid="button-new-analysis"><RefreshCw size={15} /> Start over</Button>{saved ? <Button onClick={onOpen} data-testid="button-open-saved">Open saved <ArrowRight size={15} /></Button> : <Button onClick={onSave} disabled={saving} data-testid="button-save-analysis">{saving ? 'Saving…' : <><Clipboard size={15} /> Save result</>}</Button>}</div></div><div className="grid gap-6 lg:grid-cols-[1.05fr_.95fr]"><section className="rounded-2xl border border-primary/20 bg-primary p-6 text-primary-foreground md:p-8"><div className="flex flex-wrap items-start justify-between gap-5"><div><div className="eyebrow text-accent">Recommended structure</div><h2 className="display-face mt-3 text-4xl font-bold">{result.recommendation.name}</h2><p className="mt-2 text-sm text-primary-foreground/65">{result.recommendation.polymerFamily} · {result.recommendation.category}</p></div><ScoreBadge score={result.score} strength={result.strength} /></div><div className="mt-9 grid gap-2 sm:grid-cols-4">{[['Structure', result.specifications.structure],['Thickness', result.specifications.thickness],['O₂ / WVTR', `${result.specifications.otr} / ${result.specifications.wvtr}`],['MAP', result.specifications.mapSuitability]].map(([a,b]) => <div key={a} className="rounded-xl border border-primary-foreground/10 bg-primary-foreground/5 p-3"><div className="text-[10px] text-primary-foreground/50">{a}</div><div className="mt-1 text-xs font-bold capitalize">{b}</div></div>)}</div><p className="mt-7 border-t border-primary-foreground/15 pt-5 text-sm leading-6 text-primary-foreground/75">{result.explanation}</p></section><section className="rounded-2xl border border-border bg-card p-6"><div className="eyebrow text-primary">Why it fits</div><h2 className="mt-1 text-lg font-bold">Requirement alignment</h2><div className="mt-5 space-y-3">{result.reasons.map((reason) => <div key={reason} className="flex gap-3 text-sm leading-6"><Check size={16} className="mt-1 shrink-0 text-primary" /><span>{reason}</span></div>)}</div><div className="mt-6 border-t border-border pt-5"><div className="mb-3 text-xs font-bold text-muted-foreground">Watch closely</div>{result.weakRequirements.map((item) => <div key={item} className="mb-2 flex gap-2 text-xs leading-5 text-muted-foreground"><CircleAlert size={14} className="mt-0.5 shrink-0 text-accent-foreground" />{item}</div>)}</div></section></div><div className="mt-6 grid gap-6 lg:grid-cols-3"><section className="rounded-2xl border border-border bg-card p-6 lg:col-span-2"><div className="eyebrow text-primary">Decision notes</div><div className="mt-5 grid gap-6 sm:grid-cols-2"><div><h3 className="text-sm font-bold">Shelf-life support</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">{result.shelfLifeSupport.assessment}</p><div className="mt-4 rounded-lg bg-secondary p-3 text-xs"><span className="font-bold">Target:</span> {result.shelfLifeSupport.target}</div></div><div><h3 className="text-sm font-bold">Sustainability read</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">{result.sustainability.tradeoff}</p><div className="mt-4 space-y-2 text-xs text-muted-foreground"><div><span className="font-bold text-foreground">Recyclability:</span> {result.sustainability.recyclability}</div><div><span className="font-bold text-foreground">Compostability:</span> {result.sustainability.compostability}</div></div></div></div><button type="button" onClick={() => setExpanded(!expanded)} className="mt-6 flex items-center gap-2 text-xs font-bold text-primary" data-testid="button-toggle-details">{expanded ? 'Hide detail' : 'Show controls and risks'} <ChevronRight size={14} className={cx('transition-transform', expanded && 'rotate-90')} /></button>{expanded && <div className="mt-4 grid gap-5 border-t border-border pt-5 sm:grid-cols-2"><div><div className="mb-2 text-xs font-bold">Controls</div>{result.shelfLifeSupport.controls.map((x) => <div className="mb-2 text-xs text-muted-foreground" key={x}>— {x}</div>)}</div><div><div className="mb-2 text-xs font-bold">Risks</div>{result.shelfLifeSupport.risks.map((x) => <div className="mb-2 text-xs text-muted-foreground" key={x}>— {x}</div>)}</div></div>}</section><section className="rounded-2xl border border-border bg-card p-6"><div className="eyebrow text-primary">Alternatives</div><h2 className="mt-1 text-lg font-bold">If the brief shifts</h2><div className="mt-5 space-y-4">{result.alternatives.map((item) => <div className="rounded-xl border border-border p-4" key={item.material.id}><div className="flex items-start justify-between gap-3"><div><div className="text-sm font-bold">{item.material.name}</div><div className="mt-1 text-[11px] capitalize text-muted-foreground">{item.role.replace('-', ' ')} path</div></div><span className="font-mono text-xs font-bold text-primary">{item.score}</span></div><p className="mt-3 text-xs leading-5 text-muted-foreground">{item.tradeoff}</p></div>)}</div></section></div>{result.warnings.length > 0 && <section className="mt-6 rounded-2xl border border-accent/35 bg-accent/10 p-5"><div className="flex items-center gap-2 text-sm font-bold"><CircleAlert size={17} /> Warnings to carry forward</div><div className="mt-3 grid gap-2 sm:grid-cols-2">{result.warnings.map((warning) => <div className="text-xs leading-5 text-foreground/75" key={warning}>— {warning}</div>)}</div></section>}</div>;
}

function ResultView({ result, input, saved, onSave, saving, onReset, onOpen }: { result: RecommendationResult; input: RecommendationInput; saved: number | null; onSave: () => void; saving: boolean; onReset: () => void; onOpen: () => void }) {
  return <div className="space-y-6"><ResultViewContent result={result} input={input} saved={saved} onSave={onSave} saving={saving} onReset={onReset} onOpen={onOpen} /><PackagingPreview material={result.recommendation} packageType={input.preferences.packageType} /></div>;
}

function Recommendations() {
  const [search, setSearch] = useState(''); const [storage, setStorage] = useState(''); const [sort, setSort] = useState<'newest' | 'oldest' | 'shelfLife'>('newest');
  const params = useMemo(() => ({ search: search || undefined, storageType: storage || undefined, sort }), [search, storage, sort]); const query = useListRecommendations(params);
  return <><PageIntro eyebrow="Workspace / history" title="Your decision trail." subtitle="Search saved analyses by product, route, or storage condition." action={<Link href="/recommend" className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-history-new"><Sparkles size={15} /> New recommendation</Link>} /><div className="mb-5 flex flex-col gap-3 rounded-xl border border-border bg-card p-3 md:flex-row"><div className="relative flex-1"><Search size={16} className="absolute left-3 top-3 text-muted-foreground" /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search product or material…" className="pl-9" data-testid="input-history-search" /></div><Select value={storage} onChange={(event) => setStorage(event.target.value)} className="md:w-40" data-testid="select-history-storage"><option value="">All storage</option><option value="ambient">Ambient</option><option value="chilled">Chilled</option><option value="frozen">Frozen</option></Select><Select value={sort} onChange={(event) => setSort(event.target.value as typeof sort)} className="md:w-36" data-testid="select-history-sort"><option value="newest">Newest</option><option value="oldest">Oldest</option><option value="shelfLife">Shelf life</option></Select></div>{query.isLoading ? <div className="space-y-3">{[1,2,3,4].map((x) => <Skeleton key={x} className="h-20" />)}</div> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : query.data?.length ? <div className="overflow-hidden rounded-2xl border border-border bg-card"><div className="hidden grid-cols-[1.3fr_1fr_.7fr_.7fr_24px] gap-4 border-b border-border bg-muted/40 px-5 py-3 text-[10px] font-bold uppercase tracking-wider text-muted-foreground md:grid"><span>Commodity</span><span>Material</span><span>Storage</span><span>Created</span><span /></div>{query.data.map((item) => <RecommendationRow key={item.id} item={item} />)}</div> : <EmptyState icon={History} title="No saved recommendations yet" body="Your analyzed briefs will live here, ready to revisit when the project moves forward." action={<Link href="/recommend" className="text-sm font-bold text-primary" data-testid="link-history-empty">Run your first analysis <ArrowRight size={14} className="inline" /></Link>} />}</>;
}

function RecommendationDetail() {
  const { id } = useParams<{ id: string }>(); const recommendationId = Number(id); const query = useGetRecommendation(recommendationId, { query: { queryKey: getGetRecommendationQueryKey(recommendationId), enabled: Number.isFinite(recommendationId) } }); const share = useCreateRecommendationShare(); const [shared, setShared] = useState<string | null>(null);
  if (query.isLoading) return <div className="space-y-4"><Skeleton className="h-12 w-2/3" /><Skeleton className="h-96" /></div>; if (query.isError || !query.data) return <ErrorState onRetry={() => query.refetch()} title="Recommendation not found" />; const item = query.data;
  return <><PageIntro eyebrow={`Saved recommendation / ${formatDate(item.createdAt)}`} title={item.commodityName} subtitle={`${item.category} · ${item.storageType} · ${item.shelfLife}`} action={<div className="flex gap-2"><Button variant="outline" onClick={() => share.mutate({ id: item.id }, { onSuccess: (result) => { setShared(result.url); navigator.clipboard?.writeText(result.url); } })} disabled={share.isPending} data-testid="button-share-recommendation"><Link2 size={15} /> {share.isPending ? 'Creating link…' : 'Share result'}</Button><Link href="/recommend" className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-detail-new"><Sparkles size={15} /> New analysis</Link></div>} />{shared && <div className="mb-5 flex items-center justify-between gap-3 rounded-xl border border-primary/20 bg-secondary p-4 text-sm" data-testid="status-share-created"><span><Check size={15} className="mr-2 inline text-primary" /> Link copied. Anyone with the link can view the summary.</span><button onClick={() => setShared(null)} aria-label="Dismiss" data-testid="button-dismiss-share"><X size={16} /></button></div>}<ResultDetail item={item} /></>;
}
function ResultDetailContent({ item }: { item: Recommendation }) { const result = item.result; return <div className="space-y-6"><div className="grid gap-6 lg:grid-cols-[1fr_.8fr]"><section className="rounded-2xl border border-primary/20 bg-primary p-7 text-primary-foreground"><div className="eyebrow text-accent">Recommended structure</div><h2 className="display-face mt-3 text-4xl font-bold">{result.recommendation.name}</h2><p className="mt-2 text-sm text-primary-foreground/65">{result.recommendation.polymerFamily} · {result.recommendation.category}</p><div className="mt-8 flex items-center gap-5"><ScoreBadge score={result.score} strength={result.strength} /></div><p className="mt-8 border-t border-primary-foreground/15 pt-5 text-sm leading-6 text-primary-foreground/75">{result.explanation}</p></section><section className="rounded-2xl border border-border bg-card p-6"><div className="eyebrow text-primary">Specification</div><div className="mt-5 space-y-3">{Object.entries(result.specifications).map(([key, value]) => <div key={key} className="flex justify-between gap-4 border-b border-border pb-3 text-sm last:border-0"><span className="capitalize text-muted-foreground">{key.replace(/([A-Z])/g, ' $1')}</span><span className="text-right font-semibold">{String(value)}</span></div>)}</div></section></div><div className="grid gap-6 md:grid-cols-3"><DetailList title="Matched requirements" icon={Check} items={result.matchedRequirements} /><DetailList title="Weak requirements" icon={CircleAlert} items={result.weakRequirements} /><DetailList title="Warnings" icon={Info} items={result.warnings} /></div><section className="rounded-2xl border border-border bg-card p-6"><div className="eyebrow text-primary">Material reference</div><h2 className="mt-1 text-lg font-bold">{result.recommendation.name}</h2><div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{Object.entries(result.recommendation.properties).map(([key, value]) => <div key={key} className="rounded-xl bg-muted/60 p-4"><div className="text-[10px] uppercase tracking-wider text-muted-foreground">{key.replace(/([A-Z])/g, ' $1')}</div><div className="mt-2 text-sm font-bold">{value}</div></div>)}</div></section></div>; }
function ResultDetail({ item }: { item: Recommendation }) { return <div className="space-y-6"><ResultDetailContent item={item} /><PackagingPreview material={item.result.recommendation} packageType={item.input.preferences.packageType} /></div>; }
function DetailList({ title, icon: Icon, items }: { title: string; icon: typeof Check; items: string[] }) { return <section className="rounded-2xl border border-border bg-card p-5"><div className="flex items-center gap-2 text-sm font-bold"><Icon size={16} className="text-primary" /> {title}</div><div className="mt-4 space-y-3">{items.length ? items.map((item) => <div className="text-xs leading-5 text-muted-foreground" key={item}>{item}</div>) : <div className="text-xs text-muted-foreground">None recorded.</div>}</div></section>; }

function Materials() {
  const [search, setSearch] = useState(''); const [category, setCategory] = useState(''); const [cost, setCost] = useState(''); const [sustainability, setSustainability] = useState('');
  const query = useListMaterials({ search: search || undefined, category: category || undefined, cost: cost || undefined, sustainability: sustainability || undefined }); const categories = useMemo(() => Array.from(new Set((query.data || []).map((item) => item.category))), [query.data]);
  return <><PageIntro eyebrow="Reference / material library" title="Find the right barrier." subtitle="A practical reference for the structures behind a recommendation." /><div className="mb-6 grid gap-3 rounded-2xl border border-border bg-card p-4 lg:grid-cols-[1.3fr_.8fr_.6fr_.8fr]"><div className="relative"><Search size={16} className="absolute left-3 top-3 text-muted-foreground" /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search materials…" className="pl-9" data-testid="input-material-search" /></div><Select value={category} onChange={(event) => setCategory(event.target.value)} data-testid="select-material-category"><option value="">All categories</option>{categories.map((item) => <option key={item} value={item}>{item}</option>)}</Select><Select value={cost} onChange={(event) => setCost(event.target.value)} data-testid="select-material-cost"><option value="">Any cost</option><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></Select><Select value={sustainability} onChange={(event) => setSustainability(event.target.value)} data-testid="select-material-sustainability"><option value="">Any sustainability</option><option value="recyclable">Recyclable</option><option value="compostable">Compostable</option><option value="biodegradable">Biodegradable</option></Select></div>{query.isLoading ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{[1,2,3,4,5,6].map((x) => <Skeleton key={x} className="h-64" />)}</div> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : query.data?.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{query.data.map((material) => <MaterialCard key={material.id} material={material} />)}</div> : <EmptyState icon={Database} title="No materials match that brief" body="Try a broader search or clear one of the filters." action={<Button variant="outline" onClick={() => { setSearch(''); setCategory(''); setCost(''); setSustainability(''); }} data-testid="button-clear-material-filters"><X size={15} /> Clear filters</Button>} />}</>;
}
function MaterialCard({ material }: { material: MaterialSummary }) {
  const [open, setOpen] = useState(false);
  return <><button type="button" onClick={() => setOpen(true)} className="lift block w-full rounded-2xl border border-border bg-card p-5 text-left" data-testid={`card-material-${material.id}`} aria-label={`Open technical details for ${material.name}`}><div className="flex items-start justify-between gap-4"><div className="grid h-11 w-11 place-items-center rounded-xl bg-secondary text-primary"><FlaskConical size={20} /></div><span className={cx('rounded-full px-2 py-1 text-[10px] font-bold uppercase', material.mapSuitability === 'recommended' ? 'bg-primary/10 text-primary' : 'bg-muted text-muted-foreground')}>{material.mapSuitability?.replace('-', ' ') || 'reference'}</span></div><h2 className="mt-6 text-lg font-bold">{material.name}</h2><p className="mt-1 text-xs text-muted-foreground">{material.polymerFamily || material.category}</p><p className="mt-4 line-clamp-2 text-sm leading-6 text-muted-foreground">{material.barrierSummary}</p><div className="mt-5 flex items-center justify-between border-t border-border pt-4 text-xs"><span className="capitalize text-muted-foreground">{material.sustainability}</span><span className="font-mono font-bold uppercase text-primary">{material.cost} cost <ArrowRight size={13} className="ml-1 inline" /></span></div></button>{open && <MaterialModal materialId={material.id} onClose={() => setOpen(false)} />}</>;
}
function MaterialModal({ materialId, onClose }: { materialId: string; onClose: () => void }) {
  const query = useGetMaterial(materialId, { query: { queryKey: getGetMaterialQueryKey(materialId), enabled: Boolean(materialId) } });
  useEffect(() => { const close = (event: KeyboardEvent) => event.key === 'Escape' && onClose(); window.addEventListener('keydown', close); return () => window.removeEventListener('keydown', close); }, [onClose]);
  return <div className="fixed inset-0 z-50 grid place-items-center bg-foreground/45 p-4 backdrop-blur-sm" role="dialog" aria-modal="true" aria-label="Material technical details" onPointerDown={(event) => event.target === event.currentTarget && onClose()}><div className="max-h-[90dvh] w-full max-w-5xl overflow-y-auto rounded-2xl border border-border bg-background p-5 shadow-2xl md:p-7"><div className="flex items-start justify-between gap-4"><div><div className="eyebrow text-primary">Material reference</div><h2 className="display-face mt-1 text-2xl font-bold">{query.data?.name || 'Loading material…'}</h2><p className="mt-1 text-sm text-muted-foreground">{query.data?.barrierSummary || 'Fetching technical properties and structure preview.'}</p></div><button type="button" onClick={onClose} className="grid h-9 w-9 place-items-center rounded-lg border border-border text-muted-foreground hover:bg-muted hover:text-foreground" aria-label="Close material details" data-testid="button-close-material-modal"><X size={17} /></button></div>{query.isLoading ? <div className="mt-6 space-y-3"><Skeleton className="h-64" /><Skeleton className="h-20" /></div> : query.isError || !query.data ? <div className="mt-6"><ErrorState title="Material details unavailable" onRetry={() => query.refetch()} /></div> : <div className="mt-6 grid gap-6 lg:grid-cols-[1fr_.9fr]"><PackagingPreview material={query.data} packageType={query.data.category} /><div className="space-y-5"><div className="grid gap-3 sm:grid-cols-2">{Object.entries(query.data.properties).map(([key, value]) => <div className="rounded-xl border border-border bg-card p-4" key={key}><div className="text-[10px] uppercase tracking-wider text-muted-foreground">{key.replace(/([A-Z])/g, ' $1')}</div><div className="mt-1 text-sm font-bold">{value}</div></div>)}</div><div className="grid gap-4 sm:grid-cols-2"><ListCard title="Applications" items={query.data.applications} /><ListCard title="Limitations" items={query.data.limitations} /></div><div className="rounded-xl border border-accent/25 bg-accent/10 p-4 text-xs leading-5 text-muted-foreground"><span className="font-bold text-foreground">Compatibility:</span> {query.data.compatibilityNotes.join(' · ')}</div><div className="flex flex-wrap items-center justify-between gap-3 border-t border-border pt-4"><span className="text-xs text-muted-foreground">Preview reflects the catalog profile; validate the final structure with a supplier.</span><Link href={`/materials/${query.data.id}`} onClick={onClose} className="inline-flex items-center gap-1 text-xs font-bold text-primary" data-testid="link-full-material-reference">Open full reference <ArrowRight size={13} /></Link></div></div></div>}</div></div>;
}
function MaterialDetail() { const { id } = useParams<{ id: string }>(); const materialId = id || ''; const query = useGetMaterial(materialId, { query: { queryKey: getGetMaterialQueryKey(materialId), enabled: Boolean(id) } }); if (query.isLoading) return <div className="space-y-5"><Skeleton className="h-10 w-2/3" /><Skeleton className="h-96" /></div>; if (query.isError || !query.data) return <ErrorState onRetry={() => query.refetch()} title="Material not found" />; const material = query.data; return <><Link href="/materials" className="mb-6 inline-flex items-center gap-2 text-xs font-bold text-primary" data-testid="link-back-materials"><ChevronLeft size={15} /> Back to materials</Link><PageIntro eyebrow={`Reference / ${material.category}`} title={material.name} subtitle={material.barrierSummary} action={<span className="rounded-full bg-secondary px-3 py-2 text-xs font-bold capitalize text-primary">{material.sustainability}</span>} /><div className="grid gap-6 lg:grid-cols-[1.2fr_.8fr]"><section className="rounded-2xl border border-border bg-card p-6"><div className="eyebrow text-primary">Properties</div><div className="mt-6 grid gap-3 sm:grid-cols-2">{Object.entries(material.properties).map(([key, value]) => <div className="rounded-xl border border-border p-4" key={key}><div className="text-[10px] uppercase tracking-wider text-muted-foreground">{key.replace(/([A-Z])/g, ' $1')}</div><div className="mt-2 text-sm font-bold">{value}</div></div>)}</div><div className="mt-6 grid gap-3 border-t border-border pt-5 sm:grid-cols-3">{[['Thickness', material.thicknessRange],['Recyclability', material.recyclability],['Compostability', material.compostability]].map(([a,b]) => <div key={a}><div className="text-[10px] uppercase tracking-wider text-muted-foreground">{a}</div><div className="mt-1 text-sm font-bold">{b || 'Not specified'}</div></div>)}</div></section><div className="space-y-6"><ListCard title="Applications" items={material.applications} /><ListCard title="Advantages" items={material.advantages} /><ListCard title="Limitations" items={material.limitations} /></div></div><section className="mt-6 rounded-2xl border border-accent/25 bg-accent/10 p-6"><div className="flex gap-3"><Info size={18} className="mt-0.5 text-primary" /><div><h2 className="font-bold">Compatibility notes</h2><div className="mt-3 grid gap-2 sm:grid-cols-2">{material.compatibilityNotes.map((note) => <p className="text-sm leading-6 text-muted-foreground" key={note}>— {note}</p>)}</div></div></div></section></>; }
function ListCard({ title, items }: { title: string; items: string[] }) { return <section className="rounded-2xl border border-border bg-card p-5"><h2 className="text-sm font-bold">{title}</h2><div className="mt-3 space-y-2">{items?.map((item) => <p className="text-xs leading-5 text-muted-foreground" key={item}>— {item}</p>)}</div></section>; }

function HowItWorks() { const stages = [{ icon: Clipboard, n: '01', title: 'Capture the brief', body: 'Tell us what the product is, how it behaves, where it will be stored, and how it will move.' }, { icon: SlidersHorizontal, n: '02', title: 'Weight the constraints', body: 'Choose what matters most: protection, shelf life, cost, sustainability, or a balanced view.' }, { icon: Beaker, n: '03', title: 'Model fit', body: 'PackSmart maps the brief against packaging material properties and produces a scored recommendation.' }, { icon: FileText, n: '04', title: 'Carry the decision', body: 'Save the output, compare alternatives, share a concise summary, and keep the reasoning visible.' }]; return <div className="mx-auto max-w-5xl"><PageIntro eyebrow="Method / transparent by design" title="A packaging decision is a chain, not a guess." subtitle="PackSmart makes the chain visible so your team can challenge it, improve it, and move it forward." /><div className="grid gap-4 md:grid-cols-2">{stages.map(({ icon: Icon, n, title, body }) => <div key={n} className="lift rounded-2xl border border-border bg-card p-6 md:p-8"><div className="flex items-center justify-between"><div className="grid h-11 w-11 place-items-center rounded-xl bg-secondary text-primary"><Icon size={20} /></div><span className="font-mono text-3xl font-bold text-border">{n}</span></div><h2 className="mt-10 text-xl font-bold">{title}</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">{body}</p></div>)}</div><div className="mt-7 rounded-2xl border border-primary/20 bg-primary p-7 text-primary-foreground md:p-10"><div className="eyebrow text-accent">What you get back</div><div className="mt-5 grid gap-5 sm:grid-cols-3"><div><Target size={18} className="text-accent" /><h3 className="mt-3 font-bold">A fit score</h3><p className="mt-1 text-xs leading-5 text-primary-foreground/65">A quick signal for how well the structure covers your brief.</p></div><div><BarChart3 size={18} className="text-accent" /><h3 className="mt-3 font-bold">A usable specification</h3><p className="mt-1 text-xs leading-5 text-primary-foreground/65">Barrier, thickness, sealability, and mechanical targets in one place.</p></div><div><Leaf size={18} className="text-accent" /><h3 className="mt-3 font-bold">The trade-offs</h3><p className="mt-1 text-xs leading-5 text-primary-foreground/65">Alternatives and sustainability implications, not just a winner.</p></div></div></div></div>; }
function FAQ() { const questions = [['Is PackSmart a compliance tool?', 'No. It is decision support for early packaging choices. Validate the resulting structure with your packaging supplier, process engineer, and applicable food-contact requirements.'], ['What makes a recommendation useful?', 'Specific operating context. Shelf-life target, temperature, humidity, route, handling, and product behavior all change the packaging job.'], ['Can I compare sustainability options?', 'Yes. The result includes a sustainability read and alternatives that help you see the protection trade-off behind a lower-impact option.'], ['Who is PackSmart for?', 'Farmers, processors, packaging professionals, food startups, researchers, and teams who need a shared starting point for material decisions.'], ['Can I share a result with someone outside my team?', 'Yes. Save a recommendation, create a public share link, and send the concise summary without exposing your full workspace.']]; const [active, setActive] = useState(0); return <div className="mx-auto max-w-4xl"><PageIntro eyebrow="Help / frequently asked" title="Good questions make better packages." subtitle="A short guide to using PackSmart with the right expectations." /><div className="divide-y divide-border overflow-hidden rounded-2xl border border-border bg-card">{questions.map(([q, a], index) => <div key={q}><button className="flex w-full items-center justify-between gap-5 p-5 text-left text-sm font-bold hover:bg-muted/50 md:p-6" onClick={() => setActive(active === index ? -1 : index)} data-testid={`button-faq-${index}`}><span>{q}</span><ChevronRight size={17} className={cx('shrink-0 text-primary transition-transform', active === index && 'rotate-90')} /></button>{active === index && <div className="px-5 pb-6 text-sm leading-7 text-muted-foreground md:px-6">{a}</div>}</div>)}</div></div>; }

function Profile() { const profile = useGetProfile(); const update = useUpdateProfile(); const [name, setName] = useState(''); const [userType, setUserType] = useState<ProfileInputUserType>('other'); const [initialized, setInitialized] = useState(false); useEffect(() => { if (profile.data && !initialized) { setName(profile.data.name); setUserType(profile.data.userType); setInitialized(true); } }, [profile.data, initialized]); return <div className="mx-auto max-w-3xl"><PageIntro eyebrow="Workspace / profile" title="Your working profile." subtitle="This helps PackSmart keep the interface and future decisions relevant to your role." />{profile.isLoading ? <Skeleton className="h-96" /> : profile.isError ? <ErrorState onRetry={() => profile.refetch()} /> : <section className="rounded-2xl border border-border bg-card p-6 md:p-8"><div className="grid gap-5 sm:grid-cols-2"><Field label="Name"><Input value={name} onChange={(event) => setName(event.target.value)} data-testid="input-profile-name" /></Field><Field label="Email"><Input value={profile.data?.email || ''} disabled data-testid="input-profile-email" /></Field><Field label="Working role"><Select value={userType} onChange={(event) => setUserType(event.target.value as ProfileInputUserType)} data-testid="select-profile-role"><option value="farmer">Farmer</option><option value="processor">Food processor</option><option value="manufacturer">Packaging manufacturer</option><option value="startup">Startup</option><option value="researcher">Researcher</option><option value="student">Student</option><option value="other">Other</option></Select></Field></div><div className="mt-8 flex items-center justify-between border-t border-border pt-5"><p className="text-xs text-muted-foreground">{update.isSuccess ? 'Profile saved.' : 'Changes apply to your workspace.'}</p><Button disabled={update.isPending} onClick={() => update.mutate({ data: { name, userType } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getGetProfileQueryKey() }); } })} data-testid="button-save-profile">{update.isPending ? 'Saving…' : 'Save profile'}</Button></div></section>}</div>; }

function PublicRecommendation() { const { shareId } = useParams<{ shareId: string }>(); const query = useGetPublicRecommendation(shareId || '', { query: { queryKey: getGetPublicRecommendationQueryKey(shareId || ''), enabled: Boolean(shareId) } }); return <div className="min-h-[100dvh] bg-background"><header className="mx-auto flex max-w-5xl items-center justify-between px-5 py-5 md:px-8"><Logo /><Link href="/sign-up" className="text-xs font-bold text-primary" data-testid="link-public-start">Build your own <ArrowRight size={14} className="ml-1 inline" /></Link></header><main className="mx-auto max-w-5xl px-5 pb-16 pt-10 md:px-8 md:pt-16">{query.isLoading ? <div className="space-y-5"><Skeleton className="h-12 w-2/3" /><Skeleton className="h-80" /></div> : query.isError || !query.data ? <ErrorState title="This shared recommendation is unavailable" onRetry={() => query.refetch()} /> : <div className="mx-auto max-w-3xl"><div className="eyebrow text-primary">PackSmart decision brief / {formatDate(query.data.createdAt)}</div><h1 className="display-face mt-4 text-4xl font-bold tracking-tight md:text-6xl">{query.data.commodityName}</h1><p className="mt-3 text-sm text-muted-foreground">{query.data.category} · {query.data.strength} fit · shared result</p><section className="mt-10 rounded-2xl border border-primary/20 bg-primary p-7 text-primary-foreground md:p-10"><div className="eyebrow text-accent">Recommended structure</div><div className="mt-3 flex flex-wrap items-end justify-between gap-5"><div><h2 className="display-face text-3xl font-bold md:text-4xl">{query.data.materialName}</h2><p className="mt-2 text-sm text-primary-foreground/65">{query.data.structure} · {query.data.thickness}</p></div><div className="text-right"><div className="eyebrow text-primary-foreground/50">Fit score</div><div className="mt-1 text-5xl font-bold text-accent">{query.data.score}</div></div></div><p className="mt-8 border-t border-primary-foreground/15 pt-6 text-sm leading-7 text-primary-foreground/75">{query.data.explanation}</p></section>{query.data.warnings.length > 0 && <section className="mt-5 rounded-2xl border border-accent/30 bg-accent/10 p-6"><div className="flex items-center gap-2 text-sm font-bold"><CircleAlert size={16} /> Carry-forward warnings</div><div className="mt-3 space-y-2">{query.data.warnings.map((warning) => <p key={warning} className="text-sm text-muted-foreground">— {warning}</p>)}</div></section>}<div className="mt-8 flex items-center justify-between border-t border-border pt-6 text-xs text-muted-foreground"><span>Shared from PackSmart AI</span><Link href="/sign-up" className="font-bold text-primary" data-testid="link-public-cta">Make a recommendation <ArrowRight size={13} className="ml-1 inline" /></Link></div></div>}</main></div>; }

function AuthPage({ mode }: { mode: 'sign-in' | 'sign-up' }) { const appearance = { variables: { colorPrimary: '#16473e', colorForeground: '#163d36', colorMutedForeground: '#64736e', colorBackground: '#fbfaf5', colorInput: '#f7f2e7', colorInputForeground: '#163d36', colorNeutral: '#d8d2c4', fontFamily: 'Manrope, sans-serif', borderRadius: '0.75rem' }, elements: { rootBox: 'w-full flex justify-center', cardBox: 'bg-[#fbfaf5] rounded-2xl w-[440px] max-w-full border border-[#d8d2c4] shadow-none', card: '!shadow-none !border-0 !bg-transparent', footer: '!shadow-none !border-0 !bg-transparent', headerTitle: 'text-[#163d36] font-bold', headerSubtitle: 'text-[#64736e]', formFieldLabel: 'text-[#163d36] font-semibold', footerActionLink: 'text-[#16473e] font-bold', footerActionText: 'text-[#64736e]', formButtonPrimary: 'bg-[#16473e] hover:bg-[#205b50]', formFieldInput: 'bg-[#f7f2e7] border-[#d8d2c4] text-[#163d36]', socialButtonsBlockButton: 'border-[#d8d2c4] bg-transparent', socialButtonsBlockButtonText: 'text-[#163d36]', dividerText: 'text-[#64736e]' } }; return <div className="grid min-h-[100dvh] bg-background lg:grid-cols-[.9fr_1.1fr]"><div className="hidden bg-primary p-10 text-primary-foreground lg:flex lg:flex-col lg:justify-between"><Logo inverse /><div><div className="eyebrow text-accent">PackSmart AI</div><h1 className="display-face mt-4 max-w-sm text-5xl font-bold leading-[1.02]">A better package starts with a better question.</h1><p className="mt-5 max-w-sm text-sm leading-6 text-primary-foreground/65">A focused decision-support workspace for food and packaging teams.</p></div><div className="text-xs text-primary-foreground/45">Materials intelligence for the people who move food forward.</div></div><div className="grid place-items-center px-4 py-10"><div className="w-full max-w-[440px]"><div className="mb-6 lg:hidden"><Logo /></div>{mode === 'sign-in' ? <SignIn routing="path" path={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} appearance={appearance} /> : <SignUp routing="path" path={`${basePath}/sign-up`} signInUrl={`${basePath}/sign-in`} appearance={appearance} />}</div></div></div>; }

function ClerkRoutes() {
  const [, setLocation] = useLocation();
  const stripBase = (path: string) => basePath && path.startsWith(basePath) ? path.slice(basePath.length) || '/' : path;
  return <ClerkProvider publishableKey={clerkPubKey} proxyUrl={clerkProxyUrl} signInUrl={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} routerPush={(to) => setLocation(stripBase(to))} routerReplace={(to) => setLocation(stripBase(to), { replace: true })}><QueryClientProvider client={queryClient}><Switch><Route path="/" component={HomeRedirect} /><Route path="/sign-in/*?" component={() => <AuthPage mode="sign-in" />} /><Route path="/sign-up/*?" component={() => <AuthPage mode="sign-up" />} /><Route path="/materials" component={() => <PublicShell><Materials /></PublicShell>} /><Route path="/materials/:id" component={() => <PublicShell><MaterialDetail /></PublicShell>} /><Route path="/how-it-works" component={() => <PublicShell><HowItWorks /></PublicShell>} /><Route path="/faq" component={() => <PublicShell><FAQ /></PublicShell>} /><Route path="/public/recommendation/:shareId" component={PublicRecommendation} /><Route path="/dashboard" component={() => <Protected><Dashboard /></Protected>} /><Route path="/recommend" component={() => <Protected><Recommend /></Protected>} /><Route path="/recommendations" component={() => <Protected><Recommendations /></Protected>} /><Route path="/recommendations/:id" component={() => <Protected><RecommendationDetail /></Protected>} /><Route path="/profile" component={() => <Protected><Profile /></Protected>} /><Route component={NotFound} /></Switch></QueryClientProvider></ClerkProvider>;
}

function App() { return <WouterRouter base={basePath}><ClerkRoutes /></WouterRouter>; }
export default App;
